LEVELS = ("high", "caution", "review", "no_clear_signal", "unknown")


def localize_result(result: dict, language: str) -> dict:
    """Provide independent response language; never speak or send user evidence to TTS."""
    text = CONTENT[language]
    i = LEVELS.index(result["level"])
    result["language"] = language
    result["voice_lang"] = LANGUAGE_NAMES[language][1]
    result["spoken_warning"] = text["voice"][i]
    # Display the helpline as digits without changing recorded audio or TTS input.
    result["display_warning"] = text["voice"][i].replace("one nine three zero", "1930").replace("১৯৩০", "1930")
    if not (result.get("otp_notice") and language in {"en", "hi"}):
        result["title"] = text["titles"][i]
        result["summary"] = text["summaries"][i]
    result["actions"] = list(text["actions_high"] if result["level"] in ("high", "caution") else text["actions_low"])
    if language != "en":
        for finding in result["indicators"]:
            # Keep distinct, audit-friendly reasons. Do not erase rule-specific meaning.
            finding["english_title"] = finding["title"]
            finding["english_explanation"] = finding["explanation"]
            localized = INDICATOR_COPY.get(language, {}).get(finding["id"])
            if localized:
                finding["title"], finding["explanation"] = localized
                finding["indicator_language"] = language
            else:
                # Do not invent unreviewed translations for the remaining patterns.
                finding["indicator_language"] = "en"
    return result
